SELECT *, (views * 0.1 + favorites * 0.3 + interview_count * 0.5) AS heat FROM question q WHERE q.deleted = false
AND q.type = #{type}
AND q.difficulty = #{difficulty}
AND (q.title LIKE CONCAT('%', #{keyword}, '%') OR q.content LIKE CONCAT('%', #{keyword}, '%'))
AND EXISTS ( SELECT 1 FROM question_tag qt WHERE qt.question_id = q.id AND qt.tag_id IN
#{tagId}
GROUP BY qt.question_id HAVING COUNT(DISTINCT qt.tag_id) = ${tagIds.size()} )
ORDER BY
q.interview_count ASC q.views ASC q.favorites ASC q.create_time ASC (q.views * 0.1 + q.favorites * 0.3 + q.interview_count * 0.5) ASC
ORDER BY
q.interview_count DESC q.views DESC q.favorites DESC q.create_time DESC (q.views * 0.1 + q.favorites * 0.3 + q.interview_count * 0.5) DESC
ORDER BY (q.views * 0.1 + q.favorites * 0.3 + q.interview_count * 0.5) DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM question q
WHERE q.deleted = false

    AND q.type = #{type}


    AND q.difficulty = #{difficulty}


    AND (q.title LIKE CONCAT('%', #{keyword}, '%') OR q.content LIKE CONCAT('%', #{keyword}, '%'))


    AND EXISTS (
        SELECT 1
        FROM question_tag qt
        WHERE qt.question_id = q.id
          AND qt.tag_id IN

            #{tagId}

        GROUP BY qt.question_id
        HAVING COUNT(DISTINCT qt.tag_id) = ${tagIds.size()}
    )

